<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Bella Vista Dining · Service &amp; kitchen</title><link rel="stylesheet" href="/assets/css/app.css"><link rel="stylesheet" href="/assets/css/service.css?v={{service_css_version}}"><link rel="stylesheet" href="/assets/css/ui-feedback.css"><script src="/assets/js/ui-feedback.js" defer></script><script src="/assets/js/service.js?v={{service_js_version}}" defer></script><link rel="icon" type="image/svg+xml" href="/assets/brand/bella-vista-mark.svg"></head>
<body class="service-body" data-mode="{{mode}}" data-operations="{{operations}}"><a class="skip-link" href="#service-main">Skip to workspace</a>
<header class="service-header"><a class="brand" href="/"><svg class="bella-vista-mark" viewBox="0 0 48 48" width="36" height="36" aria-hidden="true" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M9 32V21a15 15 0 0 1 30 0v11" stroke="currentColor" stroke-width="2" stroke-linecap="round"/><path d="M7 35h34M11 39c7 5 19 5 26 0M24 31V19" stroke="currentColor" stroke-width="2" stroke-linecap="round"/><path d="M24 25c-7 0-11-4-11-9 7 0 11 3 11 9Zm0-4c0-7 4-10 10-10 0 6-3 10-10 10Z" fill="currentColor"/></svg><span><b>Bella Vista</b> <small>Dining</small></span></a><nav aria-label="Staff workspaces" id="service-nav"></nav><div><span id="service-user"></span> <button type="button" id="service-logout" class="button ghost">Sign out</button></div></header>
<main id="service-main" tabindex="-1"><div class="service-title"><div><p class="eyebrow">Live dinner service</p><h1 id="service-heading">Loading workspace…</h1></div><form id="service-filters"><label>Service date<input type="date" name="date" required></label><label id="station-field" hidden>Station<select name="station" aria-label="Station"><option value="all">All stations</option><option>cold</option><option>grill</option><option>fry</option><option>hot</option><option>pastry</option><option>bar</option></select></label><button class="button ghost" type="submit">Refresh</button></form></div>
<p id="service-feedback" role="status" hidden></p><p class="muted">All outstanding service stays visible. The service date filters completed rounds and recent served tickets.</p><p id="service-sync" class="muted">Connecting…</p><div id="service-content"></div></main>
<dialog id="service-dialog" aria-labelledby="service-dialog-title"><header><h2 id="service-dialog-title"></h2><button type="button" id="service-dialog-close" class="button ghost">Close</button></header><p id="service-dialog-feedback" role="status" hidden></p><div id="service-dialog-content"></div></dialog></body></html>
